def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Background is the most common value (first cell in normal case)
    bg = grid[0][0]

    # Create output grid with background
    output = [[bg for _ in range(cols)] for _ in range(rows)]

    # Find the feature block (0s in this test case)
    feature_cells = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 0]

    if not feature_cells:
        # No feature block, just copy non-background values
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != bg:
                    output[r][c] = grid[r][c]
        return output

    # Get block boundaries
    min_r = min(c[0] for c in feature_cells)
    max_r = max(c[0] for c in feature_cells)
    min_c = min(c[1] for c in feature_cells)
    max_c = max(c[1] for c in feature_cells)

    # For each row in the feature block:
    # - First block column gets left edge value (grid[r][0])
    # - Last block column gets right edge value (grid[r][cols-1])
    # - Middle columns get background
    for r in range(min_r, max_r + 1):
        if r < rows:
            left_val = grid[r][0]
            right_val = grid[r][cols - 1]

            # Apply to block columns
            for c in range(min_c, max_c + 1):
                if c == min_c:
                    output[r][c] = left_val
                elif c == max_c:
                    output[r][c] = right_val
                else:
                    output[r][c] = bg

    return output
